WITH exploded AS (SELECT id, effective_from, currency, element FROM price_tiers LATERAL VIEW OUTER EXPLODE(discounts) e AS element) SELECT DATE_TRUNC('WEEK', effective_from) AS week_start, AVG(element) FILTER (WHERE currency = 'USD') AS usd_avg_element, SORT_ARRAY(COLLECT_SET(currency)) AS currency_list, COUNT(*) AS cnt, COUNT(*) AS num_rows FROM exploded GROUP BY DATE_TRUNC('WEEK', effective_from) ORDER BY usd_avg_element;
